<template><view class="page"><view class="head"><text class="eyebrow">企业运营</text><text class="title">数据报表</text><text class="subtitle">{{month}} 自然月统计</text></view><view class="grid-2"><view class="metric"><text class="metric-label">详情访问次数 PV</text><text class="metric-value">{{stats.pv}}</text></view><view class="metric"><text class="metric-label">访问用户数 UV</text><text class="metric-value">{{stats.uv}}</text></view><view class="metric"><text class="metric-label">兑换用户数</text><text class="metric-value">{{stats.buyers}}</text></view><view class="metric"><text class="metric-label">兑换总次数</text><text class="metric-value">{{stats.orders}}</text></view></view><view class="card conversion"><text>本月兑换转化率</text><text class="conversion-value">{{stats.conversionRate}}%</text><text class="muted">兑换用户数 ÷ 商品详情访问用户数</text></view><BottomNav role="enterprise" active="reports"/></view></template>
<script>import BottomNav from '../../components/BottomNav.vue';import {callCloud} from '../../common/cloud.js';export default{components:{BottomNav},data(){return{month:'',stats:{pv:0,uv:0,buyers:0,orders:0,conversionRate:0}}},async onShow(){const now=new Date();this.month=now.getFullYear()+'年'+(now.getMonth()+1)+'月';try{this.stats=await callCloud('product-analytics',{enterpriseId:uni.getStorageSync('user_session')?.id||'enterprise_demo',month:now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')})}catch(error){}}}</script>
<style lang="scss">@import '../../common/portal.scss';.conversion{margin-top:24rpx}.conversion-value{display:block;margin:18rpx 0;color:#006d37;font-size:60rpx;font-weight:700}</style>
